-- FEAT-076. What a governed database needs before a write request can run
-- against it.
--
-- GENERATED by `make gen` from backend/internal/feature/provision/write_support.go.
-- Do not edit: change the list there and regenerate. Avior runs the same list
-- when a database is prepared for writes on the Provisioning page, which is how
-- a governed database is brought under the write path. This file is for the
-- local fixture and for a DBA at a psql prompt.
--
--   psql "$DSN" -v owner=<role that creates the tables> -f write-support.sql
--
-- owner defaults to <database>_schema_owner and writer to avior_writer. It
-- creates no role and sets no password: deploy/store/bootstrap.sql creates the
-- writer, once per cluster. Idempotent.

\set ON_ERROR_STOP on

\if :{?writer}
\else
\set writer avior_writer
\endif
\if :{?owner}
\else
SELECT current_database() || '_schema_owner' AS owner
\gset
\endif

-- Refused here, before anything is created, when the writer is not on the server.
SELECT :'writer'::regrole AS writer_role;

SET ROLE :"owner";

SELECT format('CREATE SCHEMA IF NOT EXISTS avior_backup', current_database(), :'owner', :'writer')
\gexec

SELECT format('CREATE TABLE avior_backup.captured_row (
    request_id  uuid        NOT NULL,
    direction   text        NOT NULL,
    table_name  text        NOT NULL,
    ordinal     bigint      NOT NULL,
    row_literal text        NOT NULL,
    row_json    jsonb       NOT NULL,
    captured_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (request_id, direction, ordinal),
    CONSTRAINT captured_row_direction_known CHECK (direction IN (''before'', ''after''))
)', current_database(), :'owner', :'writer')
WHERE NOT EXISTS (SELECT 1 FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'avior_backup' AND c.relname = 'captured_row')
\gexec

SELECT format('CREATE INDEX captured_row_age_idx
    ON avior_backup.captured_row (captured_at)', current_database(), :'owner', :'writer')
WHERE NOT EXISTS (SELECT 1 FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'avior_backup' AND c.relname = 'captured_row_age_idx')
    AND EXISTS (SELECT 1 FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'avior_backup' AND c.relname = 'captured_row'
      AND c.relowner = (SELECT oid FROM pg_catalog.pg_roles WHERE rolname = current_user))
\gexec

SELECT format('GRANT CONNECT ON DATABASE %1$I TO %3$I', current_database(), :'owner', :'writer')
\gexec

SELECT format('GRANT USAGE ON SCHEMA public TO %3$I', current_database(), :'owner', :'writer')
\gexec

SELECT format('GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO %3$I', current_database(), :'owner', :'writer')
\gexec

SELECT format('ALTER DEFAULT PRIVILEGES FOR ROLE %2$I IN SCHEMA public
    GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO %3$I', current_database(), :'owner', :'writer')
\gexec

SELECT format('GRANT USAGE ON SCHEMA avior_backup TO %3$I', current_database(), :'owner', :'writer')
WHERE NOT has_schema_privilege(:'writer', 'avior_backup', 'USAGE')
\gexec

SELECT format('GRANT SELECT, INSERT, DELETE ON avior_backup.captured_row TO %3$I', current_database(), :'owner', :'writer')
WHERE NOT (has_table_privilege(:'writer', (SELECT c.oid FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'avior_backup' AND c.relname = 'captured_row'), 'SELECT')
    AND has_table_privilege(:'writer', (SELECT c.oid FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'avior_backup' AND c.relname = 'captured_row'), 'INSERT')
    AND has_table_privilege(:'writer', (SELECT c.oid FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'avior_backup' AND c.relname = 'captured_row'), 'DELETE'))
\gexec
